-- Layercake.vw_fact_contact_payment_source (src/sql/Layercake/Views/Layercake.vw_fact_contact_payment_source.sql)
/*====================================================================
    Layercake.vw_fact_contact_payment_source
    Contact payment dataset - rules view (DES-001, SPEC-001)
====================================================================*/

/*====================================================================
    One row per FO payment transaction (synapse_fo.CUSTTRANS, TRANSTYPE
    15), all legal entities and all dates, cancelled payments kept,
    test accounts (CE.tblContact_Test_Records) left out. Every business
    rule of the dataset lives here; the load only persists this output.

    Joins never multiply rows. Each lookup is an OUTER APPLY TOP (1)
    with a deterministic order, so reruns give the same result:
      - contact: the non-deleted brnz_contact with the lowest ContactId
        (RULE-015, RULE-019);
      - payment mode name: the lowest RECID for the legal entity and
        code (FO keys the table by PARTITION as well, so one legal
        entity can in principle hold the code twice);
      - country: the lowest dim_country.id for the country_id, which
        is not unique in dim_country.
    Comparisons with = ignore trailing spaces, so PAYMMODE or NAME made
    only of spaces counts as blank.

    The 'Unknown' fallbacks use ISNULL as the outermost expression so
    the view reports those columns as NOT NULL, as designed.
====================================================================*/
CREATE OR ALTER VIEW Layercake.vw_fact_contact_payment_source
AS
SELECT
    ct.DATAAREAID AS legal_entity,
    ct.RECID AS fo_transaction_recid,
    ct.ACCOUNTNUM AS account_number,
    c.Rics_contactno AS contact_number,
    -- the second argument is never used; it only makes the column NOT NULL
    ISNULL(CAST(CASE WHEN c.ContactId IS NULL THEN 1 ELSE 0 END AS bit), CAST(1 AS bit)) AS is_corporate,
    d.payment_date,
    YEAR(d.payment_date) AS payment_year,
    CAST(MONTH(d.payment_date) AS tinyint) AS payment_month,
    CAST(-ct.AMOUNTCUR AS decimal(32, 6)) AS amount_paid_currency,
    ct.CURRENCYCODE AS currency_code,
    CAST(-ct.AMOUNTMST AS decimal(32, 6)) AS amount_paid_gbp,
    ISNULL(m.paymmode, N'Unknown') AS payment_method_code,
    -- No code: the lookup cannot match, so this falls through to 'Unknown'.
    -- No row or a blank NAME for the legal entity: the code itself.
    ISNULL(NULLIF(pm.NAME, N''), ISNULL(m.paymmode, N'Unknown')) AS payment_method,
    ISNULL(dc.country_name, N'Unknown') AS country_name,
    ISNULL(dc.region_name, N'Unknown') AS region_name,
    ISNULL(dc.market_reporting_region, 'Unknown') AS market_reporting_region
FROM synapse_fo.CUSTTRANS AS ct
CROSS APPLY (
    -- Same adjusted date as synapse_fo.vwCustTrans, compared as there
    -- (the datetime against the literal), per the test design sign-off.
    SELECT CAST(
        CASE
            WHEN ct.DOCUMENTDATE <= '2021-08-23' AND YEAR(ct.DOCUMENTDATE) <> 1900 THEN ct.DOCUMENTDATE
            ELSE ct.TRANSDATE
        END AS date
    ) AS payment_date
) AS d
CROSS APPLY (
    -- NULL, empty and space-only codes are all "no payment mode"
    SELECT NULLIF(ct.PAYMMODE, N'') AS paymmode
) AS m
OUTER APPLY (
    SELECT TOP (1) pmt.NAME
    FROM synapse_fo.CUSTPAYMMODETABLE AS pmt
    WHERE pmt.DATAAREAID = ct.DATAAREAID
        AND pmt.PAYMMODE = m.paymmode
    ORDER BY pmt.RECID
) AS pm
OUTER APPLY (
    SELECT TOP (1)
        bc.ContactId,
        bc.Rics_contactno,
        bc.rics_countryid
    FROM Layercake.brnz_contact AS bc
    WHERE bc.Rics_contactno = ct.ACCOUNTNUM
        AND bc._is_deleted = 0
    ORDER BY bc.ContactId
) AS c
OUTER APPLY (
    SELECT TOP (1)
        dco.country_name,
        dco.region_name,
        dco.market_reporting_region
    FROM Layercake.dim_country AS dco
    WHERE dco.country_id = c.rics_countryid
    ORDER BY dco.id
) AS dc
WHERE ct.TRANSTYPE = 15
    AND NOT EXISTS (
        SELECT 1
        FROM CE.tblContact_Test_Records AS tr
        WHERE tr.apuk_contactnumber = ct.ACCOUNTNUM
    );
GO
